def number_existing_steps(apps, schema_editor):
    """Eski adımlar önceki sıralamayla (karar tarihi, kayıt zamanı) numaralanır; esas dosya
    bilgisiyle eşleşen son adım güncel işaretlenir."""
    Case = apps.get_model("cases", "Case")
    Step = apps.get_model("cases", "CaseStep")
    for case in Case.objects.filter(steps__isnull=False).distinct():
        steps = sorted(
            case.steps.all(),
            key=lambda s: (s.decision_date is None, s.decision_date, s.created_at, s.pk),
        )
        for position, step in enumerate(steps, start=1):
            Step.objects.filter(pk=step.pk).update(position=position)
        match = [s for s in steps if s.authority == case.authority and s.official_no == case.official_no]
        if match:
            Step.objects.filter(pk=match[-1].pk).update(is_current=True)


